{
  "_doc": "비전(이미지 입력) 모달리티 모델 — gear modality.image 가 가리키는 슬롯. 티어 json 과 같은 모양, 키는 .env 정본(claude_code 는 키 없는 구독 프로바이더). 2026-08-27 A/B 실측: opus(claude_code)≈gemini-3.1-pro 지연 동급(read 5.5s/5.2s·critic 13.2s/12.9s), opus 가 이슈 더 구체적. gemini_http 는 images 침묵 폐기라 금지(칩 task_36097123).",
  "enabled": true,
  "provider": "google",
  "model": "gemini-2.5-flash"
}

{
  "_doc": "모델 기어 시스템 단일 진실원. 텍스트 역할은 4축(분류/의식/실행/평가) → 현재 기어 → 티어(경량/중급/고급)로 해소된다. 모달리티(이미지/임베딩/동영상)는 기어 무관 별도 패스스루(각 핸들러 자체 설정). 자세한 설계는 docs/MODEL_GEAR_DESIGN.md.",
  "current_gear": "최대",
  "tiers": {
    "경량": "lightweight_ai_config.json",
    "중급": "midtier_ai_config.json",
    "고급": "system_ai_config.json"
  },
  "presets": {
    "절약": {
      "분류": "경량",
      "평가": "경량",
      "실행": "경량",
      "의식": "경량"
    },
    "균형": {
      "분류": "경량",
      "평가": "경량",
      "실행": "중급",
      "의식": "중급"
    },
    "최대": {
      "분류": "경량",
      "평가": "고급",
      "실행": "고급",
      "의식": "고급"
    }
  },
  "role_axis": {
    "classify": "분류",
    "background": "분류",
    "evaluate": "평가",
    "consciousness": "의식",
    "execution": "실행",
    "system_ai": "실행",
    "reflex": "실행",
    "translate": "실행",
    "content_text": "실행",
    "android": "실행",
    "auto_response": "실행",
    "guide_audit": "실행"
  },
  "overrides": {},
  "modality": {
    "_doc": "기어 밖 — 모달리티 고정 모델은 변속 불가(이미지 모델≠텍스트 모델). 현재 패스스루(핸들러가 자체 키 사용). 통합 지점만 표시.",
    "image": "vision_ai_config.json",
    "video": null,
    "embedding": "data/models/ibl_embedding"
  },
  "consciousness_enabled": true,
  "lane_reasoning": {
    "_doc": "차선(무의식 관문의 판정: EXECUTE/THINK/REPAIR)별 추론 예산. off=하이브리드 thinking·확장 추론 차단, default=프로바이더/티어 기본(켜짐). 2026-09-06 개정(사용자 판정 '실행 모델은 think 를 켠다, 켜는 게 기본'): EXECUTE off 를 default 로 되돌림. 09-02 실측(경량 실행 날짜 턴 10→3.5s·git 상태 99→36s, 품질 동일)은 옳았으나 변수가 틀렸다 — EXECUTE 는 '의식의 재규정이 필요 없다'는 판정이지 '추론이 필요 없다'가 아니며(08-10 상향 뒤 보고서 같은 장기 판단 작업도 EXECUTE), ep2901 부동산 31호에서 추론 토큰이 지역 판정·데이터 절단 설계 턴에 몰려 있었다. 배선 누락으로 CLI 프로바이더에는 애초에 적용된 적이 없어 지금까지의 보고서 품질은 전부 추론 켜진 채의 것. 반사급 턴에 예산을 걸려면 차선이 아니라 reflex 축·회상된 턴 크기에 걸 것(미채택).",
    "EXECUTE": "default",
    "THINK": "default",
    "REPAIR": "default"
  }
}
